const body = $input.item.json.body || $input.item.json;
const userMsg = body.mensaje || body.message || '';
const lang = (body.idioma || body.language || 'es').toLowerCase();
const phone = body.customerPhone || body.phone || '';
const sender = body.customerName || body.sender || 'Viajero';

return {
  userMsg: userMsg,
  lang: lang,
  customerPhone: phone,
  customerName: sender,
  timestamp: new Date().toISOString()
};

