parameters.jsCode:
const responseData = $input.item.json;
let replyText = '¡Pura Vida! Gracias por comunicarte con Costa Rica Tours. ¿En qué aventura podemos ayudarte hoy?';

try {
  const candidates = responseData.candidates || [];
  if (candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
    replyText = candidates[0].content.parts.map(p => p.text).join('\n');
  }
} catch (e) {
  replyText = '¡Pura Vida! Tuvimos una breve interrupción al consultar con nuestros guías locales. Por favor escríbenos a reservas@costaricatours.com o al WhatsApp +506 8795-9148.';
}

return {
  reply: replyText,
  mensaje: replyText,
  response: replyText,
  quickActions: [
    { label: 'Ver Tours La Fortuna', action: 'tours_fortuna' },
    { label: 'Disponibilidad Manuel Antonio', action: 'tours_ma' },
    { label: 'Pagar con SINPE Móvil', action: 'sinpe_info' }
  ]
};
